 20	  let index = 1;
 21	  let sawDigit = false;
 22	  let sawDot = false;
 23	  let sawExponent = false;
 24	
 25	  while (index < token.length) {
 26	    const character = token[index];
 27	
 28	    if (isDigit(character)) {
 29	      sawDigit = true;
 30	      index += 1;
 31	      continue;
 32	    }
 33	
 34	    if (character === '.' && !sawDot && !sawExponent) {
 35	      sawDot = true;
 36	      index += 1;
 37	      continue;
 38	    }
