 94	export function parseCommandLine(argv, programName = 'test14_executable') {
 95	  const values = {
 96	    a: undefined,
 97	    b: undefined,
 98	  };
 99	  const extras = [];
100	  let parsingOptions = true;
101	
102	  for (let index = 0; index < argv.length; index += 1) {
103	    const token = argv[index];
104	
105	    if (parsingOptions && (token === '-h' || token === '--help')) {
106	      return {
107	        kind: 'help',
108	        text: formatHelp(programName),
109	        exitCode: 0,
110	      };
111	    }
112	
113	    if (parsingOptions && token === '--') {
114	      parsingOptions = false;
115	      continue;
116	    }
117	
118	    if (parsingOptions && isLongOptionAssignment(token, '--a')) {
119	      values.a = token.slice(4);
120	      continue;
121	    }
122	
123	    if (parsingOptions && isLongOptionAssignment(token, '--b')) {
124	      values.b = token.slice(4);
125	      continue;
126	    }
127	
128	    if (parsingOptions && (token === '--a' || token === '--b')) {
129	      const nextToken = argv[index + 1];
130	
131	      if (nextToken === undefined || looksLikeOption(nextToken)) {
132	        return {
133	          kind: 'error',
134	          text: buildExpectedValueError(programName, token),
135	          exitCode: 2,
136	        };
137	      }
138	
139	      if (token === '--a') {
140	        values.a = nextToken;
141	      } else {
142	        values.b = nextToken;
143	      }
144	
145	      index += 1;
146	      continue;
147	    }
148	
149	    extras.push(token);
150	  }
151	
152	  const missingArguments = [];
153	
154	  if (values.a === undefined) {
155	    missingArguments.push('--a');
156	  }
157	
158	  if (values.b === undefined) {
159	    missingArguments.push('--b');
160	  }
161	
162	  if (missingArguments.length > 0) {
163	    return {
164	      kind: 'error',
165	      text: buildMissingArgumentsError(programName, missingArguments),
166	      exitCode: 2,
167	    };
168	  }
169	
170	  if (extras.length > 0) {
171	    return {
172	      kind: 'error',
173	      text: buildUnrecognizedArgumentsError(programName, extras),
174	      exitCode: 2,
175	    };
176	  }
177	
178	  return {
179	    kind: 'ok',
180	    values,
181	  };
182	}
