184	export function parseCommandLineOrExit(argv, programName = 'test14_executable') {
185	  const result = parseCommandLine(argv, programName);
186	
187	  if (result.kind === 'help') {
188	    process.stdout.write(result.text);
189	    process.exit(0);
190	  }
191	
192	  if (result.kind === 'error') {
193	    process.stderr.write(result.text);
194	    process.exit(result.exitCode);
195	  }
196	
197	  return result.values;
198	}

