 89	function slugifyHeading(text) {
 90	  let result = '';
 91	  let previousWasDash = false;
 92	
 93	  for (let index = 0; index < text.length; index += 1) {
 94	    let character = text[index];
 95	
 96	    if (character >= 'A' && character <= 'Z') {
 97	      character = character.toLowerCase();
 98	    }
