100	    const isAsciiLetter = character >= 'a' && character <= 'z';
101	    const isAsciiDigit = character >= '0' && character <= '9';
102	
103	    if (isAsciiLetter || isAsciiDigit) {
104	      result += character;
105	      previousWasDash = false;
106	      continue;
107	    }
108	
109	    if (!previousWasDash && result.length > 0) {
110	      result += '-';
111	      previousWasDash = true;
112	    }
113	  }
114	
115	  if (result.endsWith('-')) {
116	    result = result.slice(0, result.length - 1);
