184	export function renderMarkdown(source, options = {}) {
185	  const normalized = normalizeNewlines(source);
186	
187	  if (normalized.length === 0) {
188	    return '';
189	  }
190	
191	  const lines = normalized.split('\n');
192	  const parts = [];
193	  let index = 0;
194	
195	  while (index < lines.length) {
196	    const line = lines[index];
197	
198	    if (isBlankLine(line)) {
199	      index += 1;
200	      continue;
201	    }
202	
203	    const heading = parseHeading(line);
204	
205	    if (heading !== null) {
206	      parts.push(renderHeading(heading, options));
207	      index += 1;
208	      continue;
209	    }
210	
211	    const listItem = parseListItem(line);
212	
213	    if (listItem !== null) {
214	      const list = renderList(lines, index, listItem);
215	      parts.push(list.html);
216	      index = list.nextIndex;
217	      continue;
218	    }
219	
220	    const paragraph = renderParagraph(lines, index);
221	    parts.push(paragraph.html);
222	    index = paragraph.nextIndex;
223	  }
224	
225	  return parts.join('\n');
226	}

